const std = @import("std");
const plugin = @import("protobuf_plugin");

const FileDescriptorProto = @typeInfo(@TypeOf(@as(plugin.CodeGeneratorRequest, undefined).proto_file.items)).pointer.child;
const ServiceDescriptorProto = @typeInfo(@TypeOf(@as(FileDescriptorProto, undefined).service.items)).pointer.child;
const MethodDescriptorProto = @typeInfo(@TypeOf(@as(ServiceDescriptorProto, undefined).method.items)).pointer.child;

pub fn generate(
    allocator: std.mem.Allocator,
    request: plugin.CodeGeneratorRequest,
    response: *plugin.CodeGeneratorResponse,
) !void {
    if (request.parameter) |parameter| {
        if (parameter.len != 0) {
            response.@"error" = try std.fmt.allocPrint(
                allocator,
                "unsupported generator parameter: {s}",
                .{parameter},
            );
            return;
        }
    }

    var files: std.StringHashMap(*const FileDescriptorProto) = .init(allocator);
    defer files.deinit();
    for (request.proto_file.items) |*file| {
        const name = file.name orelse continue;
        try files.put(name, file);
    }

    for (request.file_to_generate.items) |name| {
        const file = files.get(name) orelse return error.MissingFileDescriptor;
        try appendFile(allocator, file, response);
    }
}

fn appendFile(
    allocator: std.mem.Allocator,
    file: *const FileDescriptorProto,
    response: *plugin.CodeGeneratorResponse,
) !void {
    const source_name = file.name orelse return error.MissingFileName;
    if (!std.mem.endsWith(u8, source_name, ".proto")) return error.InvalidProtoFileName;
    const stem = source_name[0 .. source_name.len - ".proto".len];
    const header_name = try std.fmt.allocPrint(allocator, "{s}.grpc.pb.h", .{stem});
    errdefer allocator.free(header_name);
    const source_output_name = try std.fmt.allocPrint(allocator, "{s}.grpc.pb.cc", .{stem});
    errdefer allocator.free(source_output_name);

    const header = try renderHeader(allocator, file, stem, header_name);
    errdefer allocator.free(header);
    const source = try renderSource(allocator, file, header_name);
    errdefer allocator.free(source);

    try response.file.append(allocator, .{ .name = header_name, .content = header });
    errdefer _ = response.file.pop();
    try response.file.append(allocator, .{ .name = source_output_name, .content = source });
}

fn renderHeader(
    allocator: std.mem.Allocator,
    file: *const FileDescriptorProto,
    stem: []const u8,
    header_name: []const u8,
) ![]u8 {
    var output: std.Io.Writer.Allocating = .init(allocator);
    errdefer output.deinit();
    const writer = &output.writer;
    try writer.writeAll("// Generated by protoc-gen-grpc_lite_cpp. DO NOT EDIT.\n");
    try writer.writeAll("#ifndef ");
    try writeHeaderGuard(writer, header_name);
    try writer.writeAll("\n#define ");
    try writeHeaderGuard(writer, header_name);
    try writer.print(
        "\n\n#include \"{s}.pb.h\"\n\n#include <grpc_lite/cpp/sync_service.hpp>\n#include <grpcpp/grpcpp.h>\n#include <grpcpp/impl/client_streaming_call.h>\n#include <grpcpp/impl/client_unary_call.h>\n\n#include <memory>\n\n",
        .{stem},
    );
    try openNamespaces(writer, file.package orelse "");

    for (file.service.items) |service| {
        if (!hasSupportedMethod(service)) continue;
        try renderServiceDeclaration(writer, file.package orelse "", service);
    }

    try closeNamespaces(writer, file.package orelse "");
    try writer.writeAll("\n#endif  // ");
    try writeHeaderGuard(writer, header_name);
    try writer.writeByte('\n');
    return output.toOwnedSlice();
}

fn renderServiceDeclaration(
    writer: *std.Io.Writer,
    package: []const u8,
    service: ServiceDescriptorProto,
) !void {
    const service_name = service.name orelse return error.MissingServiceName;
    try writer.writeAll("class ");
    try writeIdentifier(writer, service_name);
    try writer.writeAll(" final {\n public:\n  static constexpr const char* service_full_name() { return \"");
    if (package.len != 0) try writer.print("{s}.", .{package});
    try writer.writeAll(service_name);
    try writer.writeAll("\"; }\n\n  class StubInterface {\n   public:\n    virtual ~StubInterface() = default;\n");
    for (service.method.items) |method| {
        try writeMethodDeclaration(writer, service, method, true);
    }
    try writer.writeAll("  };\n\n  class Stub final : public StubInterface {\n   public:\n    Stub(std::shared_ptr<::grpc::ChannelInterface> channel,\n         const ::grpc::StubOptions& options);\n");
    for (service.method.items) |method| {
        try writeMethodDeclaration(writer, service, method, false);
    }
    try writer.writeAll("\n   private:\n    std::shared_ptr<::grpc::ChannelInterface> channel_;\n  };\n\n  static std::unique_ptr<Stub> NewStub(\n      const std::shared_ptr<::grpc::ChannelInterface>& channel,\n      const ::grpc::StubOptions& options = ::grpc::StubOptions());\n\n  // Methods run on reactor threads, must not block or throw, and must return\n  // promptly after dispatch. EventService must outlive its registered Server.\n  class EventService {\n   public:\n    virtual ~EventService() = default;\n    ::grpc_lite::Error Register(::grpc_lite::Server& server);\n");
    for (service.method.items) |method| try writeEventMethodDeclaration(writer, service, method);
    try writer.writeAll("\n   private:\n");
    for (service.method.items) |method| try writeRegistrationMember(writer, service, method);
    try writer.writeAll("  };\n\n  class Service {\n   public:\n    virtual ~Service() = default;\n");
    for (service.method.items) |method| try writeSynchronousMethodDeclaration(writer, service, method);
    try writer.writeAll("\n    std::unique_ptr<");
    try writeIdentifier(writer, service_name);
    try writer.writeAll("::EventService> CreateEventService(\n        ::grpc_lite::ServerExecutor& executor,\n        ::grpc_lite::SynchronousServiceOptions options = {});\n  };\n};\n\n");
}

fn writeMethodDeclaration(
    writer: *std.Io.Writer,
    service: ServiceDescriptorProto,
    method: MethodDescriptorProto,
    pure_virtual: bool,
) !void {
    const name = method.name orelse return error.MissingMethodName;
    const input = method.input_type orelse return error.MissingInputType;
    const output = method.output_type orelse return error.MissingOutputType;
    const client_streaming = method.client_streaming orelse false;
    const server_streaming = method.server_streaming orelse false;
    try writer.writeAll("    virtual ");
    if (client_streaming and server_streaming) {
        try writer.writeAll("std::unique_ptr<::grpc::ClientReaderWriter<");
        try writeCppType(writer, input);
        try writer.writeAll(", ");
        try writeCppType(writer, output);
        try writer.writeAll(">> ");
    } else if (client_streaming) {
        try writer.writeAll("std::unique_ptr<::grpc::ClientWriter<");
        try writeCppType(writer, input);
        try writer.writeAll(">> ");
    } else if (server_streaming) {
        try writer.writeAll("std::unique_ptr<::grpc::ClientReader<");
        try writeCppType(writer, output);
        try writer.writeAll(">> ");
    } else {
        try writer.writeAll("::grpc::Status ");
    }
    try writeMethodIdentifier(writer, service, name, .stub);
    try writer.writeAll("(\n        ::grpc::ClientContext* context");
    if (client_streaming and !server_streaming) {
        try writer.writeAll(",\n        ");
        try writeCppType(writer, output);
        try writer.writeAll("* response");
    } else if (!client_streaming) {
        try writer.writeAll(",\n        const ");
        try writeCppType(writer, input);
        try writer.writeAll("& request");
        if (!server_streaming) {
            try writer.writeAll(",\n        ");
            try writeCppType(writer, output);
            try writer.writeAll("* response");
        }
    }
    try writer.writeByte(')');
    if (pure_virtual) {
        try writer.writeAll(" = 0;\n");
    } else {
        try writer.writeAll(" override;\n");
    }
}

fn writeEventMethodDeclaration(writer: *std.Io.Writer, service: ServiceDescriptorProto, method: MethodDescriptorProto) !void {
    const name = method.name orelse return error.MissingMethodName;
    const input = method.input_type orelse return error.MissingInputType;
    const output = method.output_type orelse return error.MissingOutputType;
    const client_streaming = method.client_streaming orelse false;
    const server_streaming = method.server_streaming orelse false;
    try writer.writeAll("    virtual void ");
    try writeMethodIdentifier(writer, service, name, .event);
    try writer.writeAll("(const ::grpc_lite::ServerContext& context, ");
    if (!client_streaming) {
        try writeCppType(writer, input);
        try writer.writeAll(" request, ");
    }
    try writer.writeAll("::grpc_lite::");
    if (client_streaming and server_streaming) {
        try writer.writeAll("BidirectionalStreamingCall<");
        try writeCppType(writer, input);
        try writer.writeAll(", ");
        try writeCppType(writer, output);
    } else if (client_streaming) {
        try writer.writeAll("ClientStreamingCall<");
        try writeCppType(writer, input);
        try writer.writeAll(", ");
        try writeCppType(writer, output);
    } else {
        try writer.writeAll(if (server_streaming) "ServerStreamingCall<" else "UnaryCall<");
        try writeCppType(writer, output);
    }
    try writer.writeAll("> call) noexcept = 0;\n");
}

fn writeSynchronousMethodDeclaration(writer: *std.Io.Writer, service: ServiceDescriptorProto, method: MethodDescriptorProto) !void {
    const name = method.name orelse return error.MissingMethodName;
    const input = method.input_type orelse return error.MissingInputType;
    const output = method.output_type orelse return error.MissingOutputType;
    const client_streaming = method.client_streaming orelse false;
    const server_streaming = method.server_streaming orelse false;
    try writer.writeAll("    virtual ::grpc::Status ");
    try writeMethodIdentifier(writer, service, name, .synchronous);
    try writer.writeAll("(::grpc::ServerContext* context, ");
    if (client_streaming and server_streaming) {
        try writer.writeAll("::grpc::ServerReaderWriter<");
        try writeCppType(writer, output);
        try writer.writeAll(", ");
        try writeCppType(writer, input);
        try writer.writeAll(">* stream);\n");
    } else if (client_streaming) {
        try writer.writeAll("::grpc::ServerReader<");
        try writeCppType(writer, input);
        try writer.writeAll(">* reader, ");
        try writeCppType(writer, output);
        try writer.writeAll("* response);\n");
    } else {
        try writer.writeAll("const ");
        try writeCppType(writer, input);
        try writer.writeAll("* request, ");
        if (server_streaming) {
            try writer.writeAll("::grpc::ServerWriter<");
            try writeCppType(writer, output);
            try writer.writeAll(">* writer);\n");
        } else {
            try writeCppType(writer, output);
            try writer.writeAll("* response);\n");
        }
    }
}

fn writeRegistrationMember(
    writer: *std.Io.Writer,
    service: ServiceDescriptorProto,
    method: MethodDescriptorProto,
) !void {
    const name = method.name orelse return error.MissingMethodName;
    const input = method.input_type orelse return error.MissingInputType;
    const output = method.output_type orelse return error.MissingOutputType;
    try writer.writeAll("    ::grpc_lite::internal::TypedMethodRegistration<");
    try writeCppType(writer, input);
    try writer.writeAll(", ");
    try writeCppType(writer, output);
    try writer.print(", {s}, {s}> ", .{
        if (method.client_streaming orelse false) "true" else "false",
        if (method.server_streaming orelse false) "true" else "false",
    });
    try writeRegistrationIdentifier(writer, service, name);
    try writer.writeAll(";\n");
}

fn writeRegistrationIdentifier(
    writer: *std.Io.Writer,
    service: ServiceDescriptorProto,
    method_name: []const u8,
) !void {
    try writer.print("grpc_lite_registration_{d}_", .{methodIndex(service, method_name)});
}

fn renderSource(
    allocator: std.mem.Allocator,
    file: *const FileDescriptorProto,
    header_name: []const u8,
) ![]u8 {
    var output: std.Io.Writer.Allocating = .init(allocator);
    errdefer output.deinit();
    const writer = &output.writer;
    try writer.print(
        "// Generated by protoc-gen-grpc_lite_cpp. DO NOT EDIT.\n#include \"{s}\"\n\n#include <utility>\n\n",
        .{header_name},
    );
    try openNamespaces(writer, file.package orelse "");
    const package = file.package orelse "";
    for (file.service.items) |service| {
        if (!hasSupportedMethod(service)) continue;
        try renderServiceDefinition(writer, package, service);
    }
    try closeNamespaces(writer, package);
    return output.toOwnedSlice();
}

fn renderServiceDefinition(
    writer: *std.Io.Writer,
    package: []const u8,
    service: ServiceDescriptorProto,
) !void {
    const service_name = service.name orelse return error.MissingServiceName;
    try writeIdentifier(writer, service_name);
    try writer.writeAll("::Stub::Stub(std::shared_ptr<::grpc::ChannelInterface> channel,\n                  const ::grpc::StubOptions& options)\n    : channel_(std::move(channel)) {\n  (void)options;\n}\n\n");

    for (service.method.items) |method| {
        const method_name = method.name orelse return error.MissingMethodName;
        const input = method.input_type orelse return error.MissingInputType;
        const output = method.output_type orelse return error.MissingOutputType;
        const client_streaming = method.client_streaming orelse false;
        const server_streaming = method.server_streaming orelse false;
        if (client_streaming and server_streaming) {
            try writer.writeAll("std::unique_ptr<::grpc::ClientReaderWriter<");
            try writeCppType(writer, input);
            try writer.writeAll(", ");
            try writeCppType(writer, output);
            try writer.writeAll(">> ");
        } else if (client_streaming) {
            try writer.writeAll("std::unique_ptr<::grpc::ClientWriter<");
            try writeCppType(writer, input);
            try writer.writeAll(">> ");
        } else if (server_streaming) {
            try writer.writeAll("std::unique_ptr<::grpc::ClientReader<");
            try writeCppType(writer, output);
            try writer.writeAll(">> ");
        } else {
            try writer.writeAll("::grpc::Status ");
        }
        try writeIdentifier(writer, service_name);
        try writer.writeAll("::Stub::");
        try writeMethodIdentifier(writer, service, method_name, .stub);
        try writer.writeAll("(\n    ::grpc::ClientContext* context");
        if (client_streaming and !server_streaming) {
            try writer.writeAll(", ");
            try writeCppType(writer, output);
            try writer.writeAll("* response");
        } else if (!client_streaming) {
            try writer.writeAll(", const ");
            try writeCppType(writer, input);
            try writer.writeAll("& request");
            if (!server_streaming) {
                try writer.writeAll(",\n    ");
                try writeCppType(writer, output);
                try writer.writeAll("* response");
            }
        }
        try writer.writeAll(") {\n  static const ::grpc::internal::RpcMethod method(\"");
        try writer.writeByte('/');
        if (package.len != 0) try writer.print("{s}.", .{package});
        try writer.print("{s}/{s}\");\n  return ::grpc::internal::", .{
            service_name,
            method_name,
        });
        if (client_streaming and server_streaming) {
            try writer.writeAll("BlockingBidiStreamingCall");
        } else if (client_streaming) {
            try writer.writeAll("BlockingClientStreamingCall");
        } else if (server_streaming) {
            try writer.writeAll("BlockingServerStreamingCall");
        } else {
            try writer.writeAll("BlockingUnaryCall");
        }
        if (client_streaming or server_streaming) {
            try writer.writeByte('<');
            try writeCppType(writer, input);
            try writer.writeAll(", ");
            try writeCppType(writer, output);
            try writer.writeByte('>');
        }
        try writer.writeAll("(\n      channel_.get(), method, context");
        if (client_streaming and !server_streaming) {
            try writer.writeAll(", response");
        } else if (!client_streaming) {
            try writer.writeAll(", request");
            if (!server_streaming) try writer.writeAll(", response");
        }
        try writer.writeAll(");\n}\n\n");
    }

    try writer.writeAll("std::unique_ptr<");
    try writeIdentifier(writer, service_name);
    try writer.writeAll("::Stub> ");
    try writeIdentifier(writer, service_name);
    try writer.writeAll("::NewStub(\n    const std::shared_ptr<::grpc::ChannelInterface>& channel,\n    const ::grpc::StubOptions& options) {\n  return std::unique_ptr<Stub>(new Stub(channel, options));\n}\n\n");

    try writer.writeAll("::grpc_lite::Error ");
    try writeIdentifier(writer, service_name);
    try writer.writeAll("::EventService::Register(::grpc_lite::Server& server) {\n  ::grpc_lite::Error error;\n");
    for (service.method.items) |method| {
        const method_name = method.name orelse return error.MissingMethodName;
        const input = method.input_type orelse return error.MissingInputType;
        const output = method.output_type orelse return error.MissingOutputType;
        const client_streaming = method.client_streaming orelse false;
        const server_streaming = method.server_streaming orelse false;
        try writer.writeAll("  error = ");
        try writeRegistrationIdentifier(writer, service, method_name);
        try writer.writeAll(".Register(server, \"");
        try writer.writeByte('/');
        if (package.len != 0) try writer.print("{s}.", .{package});
        try writer.print("{s}/{s}\",\n      [this](const ::grpc_lite::ServerContext& context, ", .{ service_name, method_name });
        if (!client_streaming) {
            try writeCppType(writer, input);
            try writer.writeAll(" request, ");
        }
        try writer.writeAll("::grpc_lite::");
        if (client_streaming and server_streaming) {
            try writer.writeAll("BidirectionalStreamingCall<");
            try writeCppType(writer, input);
            try writer.writeAll(", ");
            try writeCppType(writer, output);
        } else if (client_streaming) {
            try writer.writeAll("ClientStreamingCall<");
            try writeCppType(writer, input);
            try writer.writeAll(", ");
            try writeCppType(writer, output);
        } else {
            try writer.writeAll(if (server_streaming) "ServerStreamingCall<" else "UnaryCall<");
            try writeCppType(writer, output);
        }
        try writer.writeAll("> call) {\n        ");
        try writeMethodIdentifier(writer, service, method_name, .event);
        try writer.writeAll("(context, ");
        if (!client_streaming) try writer.writeAll("std::move(request), ");
        try writer.writeAll("std::move(call));\n      });\n  if (!error.ok()) return error;\n");
    }
    try writer.writeAll("  return {};\n}\n\n");

    for (service.method.items) |method| {
        const method_name = method.name orelse return error.MissingMethodName;
        const input = method.input_type orelse return error.MissingInputType;
        const output = method.output_type orelse return error.MissingOutputType;
        const client_streaming = method.client_streaming orelse false;
        const server_streaming = method.server_streaming orelse false;
        try writer.writeAll("::grpc::Status ");
        try writeIdentifier(writer, service_name);
        try writer.writeAll("::Service::");
        try writeMethodIdentifier(writer, service, method_name, .synchronous);
        try writer.writeAll("(::grpc::ServerContext* context, ");
        if (client_streaming and server_streaming) {
            try writer.writeAll("::grpc::ServerReaderWriter<");
            try writeCppType(writer, output);
            try writer.writeAll(", ");
            try writeCppType(writer, input);
            try writer.writeAll(">* stream)");
        } else if (client_streaming) {
            try writer.writeAll("::grpc::ServerReader<");
            try writeCppType(writer, input);
            try writer.writeAll(">* reader, ");
            try writeCppType(writer, output);
            try writer.writeAll("* response)");
        } else {
            try writer.writeAll("const ");
            try writeCppType(writer, input);
            try writer.writeAll("* request, ");
            if (server_streaming) {
                try writer.writeAll("::grpc::ServerWriter<");
                try writeCppType(writer, output);
                try writer.writeAll(">* writer)");
            } else {
                try writeCppType(writer, output);
                try writer.writeAll("* response)");
            }
        }
        try writer.writeAll(" {\n  (void)context;\n  (void)");
        if (client_streaming and server_streaming) {
            try writer.writeAll("stream");
        } else if (client_streaming) {
            try writer.writeAll("reader;\n  (void)response");
        } else {
            try writer.writeAll("request;\n  (void)");
            try writer.writeAll(if (server_streaming) "writer" else "response");
        }
        try writer.writeAll(";\n  return {::grpc::StatusCode::UNIMPLEMENTED, \"\"};\n}\n\n");
    }

    try writer.writeAll("std::unique_ptr<");
    try writeIdentifier(writer, service_name);
    try writer.writeAll("::EventService> ");
    try writeIdentifier(writer, service_name);
    try writer.writeAll("::Service::CreateEventService(\n    ::grpc_lite::ServerExecutor& executor,\n    ::grpc_lite::SynchronousServiceOptions options) {\n  class Adapter final : public ");
    try writeIdentifier(writer, service_name);
    try writer.writeAll("::EventService {\n   public:\n    Adapter(");
    try writeIdentifier(writer, service_name);
    try writer.writeAll("::Service& service, ::grpc_lite::ServerExecutor& executor,\n            ::grpc_lite::SynchronousServiceOptions options)\n        : service_(service), executor_(executor), options_(options) {}\n\n");
    for (service.method.items) |method| {
        const method_name = method.name orelse return error.MissingMethodName;
        const input = method.input_type orelse return error.MissingInputType;
        const output = method.output_type orelse return error.MissingOutputType;
        const client_streaming = method.client_streaming orelse false;
        const server_streaming = method.server_streaming orelse false;
        try writer.writeAll("    void ");
        try writeMethodIdentifier(writer, service, method_name, .event);
        try writer.writeAll("(const ::grpc_lite::ServerContext& context, ");
        if (!client_streaming) {
            try writeCppType(writer, input);
            try writer.writeAll(" request, ");
        }
        try writer.writeAll("::grpc_lite::");
        if (client_streaming and server_streaming) {
            try writer.writeAll("BidirectionalStreamingCall<");
            try writeCppType(writer, input);
            try writer.writeAll(", ");
            try writeCppType(writer, output);
        } else if (client_streaming) {
            try writer.writeAll("ClientStreamingCall<");
            try writeCppType(writer, input);
            try writer.writeAll(", ");
            try writeCppType(writer, output);
        } else {
            try writer.writeAll(if (server_streaming) "ServerStreamingCall<" else "UnaryCall<");
            try writeCppType(writer, output);
        }
        try writer.writeAll("> call) noexcept override {\n      ::grpc_lite::internal::");
        if (client_streaming and server_streaming) {
            try writer.writeAll("DispatchBidirectionalStreaming");
        } else if (client_streaming) {
            try writer.writeAll("DispatchClientStreaming");
        } else if (server_streaming) {
            try writer.writeAll("DispatchServerStreaming");
        } else {
            try writer.writeAll("DispatchUnary");
        }
        try writer.writeAll("(\n          executor_, \"");
        try writer.writeByte('/');
        if (package.len != 0) try writer.print("{s}.", .{package});
        try writer.print("{s}/{s}\", options_, context, ", .{ service_name, method_name });
        if (!client_streaming) try writer.writeAll("std::move(request),\n          ");
        try writer.writeAll("std::move(call), [service = &service_](::grpc::ServerContext* server_context,\n                                                ");
        if (client_streaming and server_streaming) {
            try writer.writeAll("::grpc::ServerReaderWriter<");
            try writeCppType(writer, output);
            try writer.writeAll(", ");
            try writeCppType(writer, input);
            try writer.writeAll(">* stream");
        } else if (client_streaming) {
            try writer.writeAll("::grpc::ServerReader<");
            try writeCppType(writer, input);
            try writer.writeAll(">* reader, ");
            try writeCppType(writer, output);
            try writer.writeAll("* response");
        } else {
            try writer.writeAll("const ");
            try writeCppType(writer, input);
            try writer.writeAll("* typed_request, ");
            if (server_streaming) {
                try writer.writeAll("::grpc::ServerWriter<");
                try writeCppType(writer, output);
                try writer.writeAll(">* writer");
            } else {
                try writeCppType(writer, output);
                try writer.writeAll("* response");
            }
        }
        try writer.writeAll(") {\n            return service->");
        try writeMethodIdentifier(writer, service, method_name, .synchronous);
        try writer.writeAll("(server_context, ");
        if (client_streaming and server_streaming) {
            try writer.writeAll("stream");
        } else if (client_streaming) {
            try writer.writeAll("reader, response");
        } else {
            try writer.writeAll("typed_request, ");
            try writer.writeAll(if (server_streaming) "writer" else "response");
        }
        try writer.writeAll(");\n          });\n    }\n\n");
    }
    try writer.writeAll("   private:\n    ");
    try writeIdentifier(writer, service_name);
    try writer.writeAll("::Service& service_;\n    ::grpc_lite::ServerExecutor& executor_;\n    ::grpc_lite::SynchronousServiceOptions options_;\n  };\n\n  return std::unique_ptr<");
    try writeIdentifier(writer, service_name);
    try writer.writeAll("::EventService>(new Adapter(*this, executor, options));\n}\n\n");
}

fn hasSupportedMethod(service: ServiceDescriptorProto) bool {
    return service.method.items.len != 0;
}

fn openNamespaces(writer: *std.Io.Writer, package: []const u8) !void {
    var components = std.mem.splitScalar(u8, package, '.');
    while (components.next()) |component| {
        if (component.len == 0) continue;
        try writer.writeAll("namespace ");
        try writeIdentifier(writer, component);
        try writer.writeAll(" {\n");
    }
    if (package.len != 0) try writer.writeByte('\n');
}

fn closeNamespaces(writer: *std.Io.Writer, package: []const u8) !void {
    var count: usize = 0;
    var components = std.mem.splitScalar(u8, package, '.');
    while (components.next()) |component| if (component.len != 0) {
        count += 1;
    };
    if (count != 0) try writer.writeByte('\n');
    while (count != 0) : (count -= 1) try writer.writeAll("}  // namespace\n");
}

fn writeCppType(writer: *std.Io.Writer, proto_type: []const u8) !void {
    try writer.writeAll("::");
    const name = if (proto_type.len != 0 and proto_type[0] == '.') proto_type[1..] else proto_type;
    var components = std.mem.splitScalar(u8, name, '.');
    var first = true;
    while (components.next()) |component| {
        if (!first) try writer.writeAll("::");
        try writeIdentifier(writer, component);
        first = false;
    }
}

fn writeHeaderGuard(writer: *std.Io.Writer, name: []const u8) !void {
    for (name) |character| {
        if (std.ascii.isAlphanumeric(character)) {
            try writer.writeByte(std.ascii.toUpper(character));
        } else {
            try writer.writeByte('_');
        }
    }
    try writer.writeByte('_');
}

fn writeIdentifier(writer: *std.Io.Writer, identifier: []const u8) !void {
    try writer.writeAll(identifier);
    if (isCppKeyword(identifier)) try writer.writeByte('_');
}

const MethodScope = enum { stub, event, synchronous };

fn writeMethodIdentifier(
    writer: *std.Io.Writer,
    service: ServiceDescriptorProto,
    identifier: []const u8,
    scope: MethodScope,
) !void {
    try writeIdentifier(writer, identifier);
    try writer.splatByteAll('_', methodSuffix(service, methodIndex(service, identifier), scope));
}

fn methodIndex(service: ServiceDescriptorProto, identifier: []const u8) usize {
    for (service.method.items, 0..) |method, index| {
        if (std.mem.eql(u8, method.name orelse continue, identifier)) return index;
    }
    unreachable;
}

fn methodSuffix(service: ServiceDescriptorProto, index: usize, scope: MethodScope) usize {
    const identifier = service.method.items[index].name orelse unreachable;
    var suffix: usize = 0;
    while (true) : (suffix += 1) {
        if (methodCollidesWithReserved(service, identifier, suffix, scope)) continue;
        for (service.method.items[0..index], 0..) |previous, previous_index| {
            const previous_name = previous.name orelse unreachable;
            const candidate_len = renderedIdentifierLen(identifier, suffix);
            const previous_base_len = renderedIdentifierLen(previous_name, 0);
            if (candidate_len < previous_base_len) continue;
            const required_previous_suffix = candidate_len - previous_base_len;
            if (!renderedIdentifiersEqual(
                identifier,
                suffix,
                previous_name,
                required_previous_suffix,
            )) continue;
            if (required_previous_suffix ==
                methodSuffix(service, previous_index, scope)) break;
        } else return suffix;
    }
}

fn methodCollidesWithReserved(
    service: ServiceDescriptorProto,
    identifier: []const u8,
    suffix: usize,
    scope: MethodScope,
) bool {
    const reserved: []const []const u8 = switch (scope) {
        .stub => &.{ "StubInterface", "Stub" },
        .event => &.{ "EventService", "Register" },
        .synchronous => &.{ "Service", "CreateEventService" },
    };
    for (reserved) |name| {
        if (renderedIdentifierEquals(identifier, suffix, name)) return true;
    }
    if (scope == .event) {
        for (service.method.items, 0..) |_, registration_index| {
            var buffer: [64]u8 = undefined;
            const registration = std.fmt.bufPrint(
                &buffer,
                "grpc_lite_registration_{d}_",
                .{registration_index},
            ) catch unreachable;
            if (renderedIdentifierEquals(identifier, suffix, registration)) return true;
        }
    }
    return false;
}

fn renderedIdentifiersEqual(first: []const u8, first_suffix: usize, second: []const u8, second_suffix: usize) bool {
    const first_len = renderedIdentifierLen(first, first_suffix);
    if (first_len != renderedIdentifierLen(second, second_suffix)) return false;
    for (0..first_len) |index| {
        if (renderedIdentifierByte(first, first_suffix, index) !=
            renderedIdentifierByte(second, second_suffix, index)) return false;
    }
    return true;
}

fn renderedIdentifierEquals(identifier: []const u8, suffix: usize, value: []const u8) bool {
    if (renderedIdentifierLen(identifier, suffix) != value.len) return false;
    for (value, 0..) |byte, index| {
        if (renderedIdentifierByte(identifier, suffix, index) != byte) return false;
    }
    return true;
}

fn renderedIdentifierLen(identifier: []const u8, suffix: usize) usize {
    return identifier.len + @intFromBool(isCppKeyword(identifier)) + suffix;
}

fn renderedIdentifierByte(identifier: []const u8, suffix: usize, index: usize) u8 {
    _ = suffix;
    if (index < identifier.len) return identifier[index];
    return '_';
}

fn isCppKeyword(identifier: []const u8) bool {
    const keywords = [_][]const u8{
        "alignas",     "alignof",   "and",              "and_eq",       "asm",      "auto",         "bitand",    "bitor",    "bool",     "break",
        "case",        "catch",     "char",             "char8_t",      "char16_t", "char32_t",     "class",     "compl",    "concept",  "const",
        "consteval",   "constexpr", "constinit",        "const_cast",   "continue", "co_await",     "co_return", "co_yield", "decltype", "default",
        "delete",      "do",        "double",           "dynamic_cast", "else",     "enum",         "explicit",  "export",   "extern",   "false",
        "float",       "for",       "friend",           "goto",         "if",       "inline",       "int",       "long",     "mutable",  "namespace",
        "new",         "noexcept",  "not",              "not_eq",       "nullptr",  "operator",     "or",        "or_eq",    "private",  "protected",
        "public",      "register",  "reinterpret_cast", "requires",     "return",   "short",        "signed",    "sizeof",   "static",   "static_assert",
        "static_cast", "struct",    "switch",           "template",     "this",     "thread_local", "throw",     "true",     "try",      "typedef",
        "typeid",      "typename",  "union",            "unsigned",     "using",    "virtual",      "void",      "volatile", "wchar_t",  "while",
        "xor",         "xor_eq",
    };
    for (keywords) |keyword| if (std.mem.eql(u8, identifier, keyword)) return true;
    return false;
}

test "generates all streaming cardinalities" {
    var arena_state = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena_state.deinit();
    const allocator = arena_state.allocator();
    var request: plugin.CodeGeneratorRequest = .{};
    try request.file_to_generate.append(allocator, "demo/echo.proto");
    var file: FileDescriptorProto = .{ .name = "demo/echo.proto", .package = "demo" };
    var service: ServiceDescriptorProto = .{ .name = "EchoService" };
    try service.method.append(allocator, .{
        .name = "Echo",
        .input_type = ".demo.EchoRequest",
        .output_type = ".demo.EchoReply",
    });
    try service.method.append(allocator, .{
        .name = "Watch",
        .input_type = ".demo.EchoRequest",
        .output_type = ".demo.EchoReply",
        .server_streaming = true,
    });
    try service.method.append(allocator, .{
        .name = "Collect",
        .input_type = ".demo.EchoRequest",
        .output_type = ".demo.EchoReply",
        .client_streaming = true,
    });
    try service.method.append(allocator, .{
        .name = "Chat",
        .input_type = ".demo.EchoRequest",
        .output_type = ".demo.EchoReply",
        .client_streaming = true,
        .server_streaming = true,
    });
    try file.service.append(allocator, service);
    try request.proto_file.append(allocator, file);

    var response: plugin.CodeGeneratorResponse = .{};
    try generate(allocator, request, &response);
    try std.testing.expectEqual(@as(usize, 2), response.file.items.len);
    try std.testing.expectEqualStrings("demo/echo.grpc.pb.h", response.file.items[0].name.?);
    try std.testing.expect(std.mem.indexOf(u8, response.file.items[0].content.?, "virtual ::grpc::Status Echo(") != null);
    try std.testing.expect(std.mem.indexOf(u8, response.file.items[0].content.?, "std::unique_ptr<::grpc::ClientReader<::demo::EchoReply>> Watch(") != null);
    try std.testing.expect(std.mem.indexOf(u8, response.file.items[0].content.?, "std::unique_ptr<::grpc::ClientWriter<::demo::EchoRequest>> Collect(") != null);
    try std.testing.expect(std.mem.indexOf(u8, response.file.items[0].content.?, "std::unique_ptr<::grpc::ClientReaderWriter<::demo::EchoRequest, ::demo::EchoReply>> Chat(") != null);
    try std.testing.expect(std.mem.indexOf(u8, response.file.items[0].content.?, "virtual void Watch(const ::grpc_lite::ServerContext& context") != null);
    try std.testing.expect(std.mem.indexOf(u8, response.file.items[0].content.?, "::grpc_lite::ClientStreamingCall<::demo::EchoRequest, ::demo::EchoReply> call") != null);
    try std.testing.expect(std.mem.indexOf(u8, response.file.items[0].content.?, "::grpc_lite::BidirectionalStreamingCall<::demo::EchoRequest, ::demo::EchoReply> call") != null);
    try std.testing.expect(std.mem.indexOf(u8, response.file.items[0].content.?, "class Service") != null);
    try std.testing.expect(std.mem.indexOf(u8, response.file.items[0].content.?, "virtual ::grpc::Status Echo(::grpc::ServerContext* context") != null);
    try std.testing.expect(std.mem.indexOf(u8, response.file.items[0].content.?, "::grpc::ServerWriter<::demo::EchoReply>* writer") != null);
    try std.testing.expect(std.mem.indexOf(u8, response.file.items[0].content.?, "::grpc::ServerReader<::demo::EchoRequest>* reader") != null);
    try std.testing.expect(std.mem.indexOf(u8, response.file.items[0].content.?, "::grpc::ServerReaderWriter<::demo::EchoReply, ::demo::EchoRequest>* stream") != null);
    try std.testing.expect(std.mem.indexOf(u8, response.file.items[0].content.?, "CreateEventService(") != null);
    try std.testing.expect(std.mem.indexOf(u8, response.file.items[0].content.?, "return \"demo.EchoService\"") != null);
    try std.testing.expect(std.mem.indexOf(u8, response.file.items[1].content.?, "/demo.EchoService/Echo") != null);
    try std.testing.expect(std.mem.indexOf(u8, response.file.items[1].content.?, "/demo.EchoService/Watch") != null);
    try std.testing.expect(std.mem.indexOf(u8, response.file.items[1].content.?, "/demo.EchoService/Collect") != null);
    try std.testing.expect(std.mem.indexOf(u8, response.file.items[1].content.?, "/demo.EchoService/Chat") != null);
    try std.testing.expect(std.mem.indexOf(u8, response.file.items[1].content.?, "BlockingServerStreamingCall") != null);
    try std.testing.expect(std.mem.indexOf(u8, response.file.items[1].content.?, "BlockingClientStreamingCall") != null);
    try std.testing.expect(std.mem.indexOf(u8, response.file.items[1].content.?, "BlockingBidiStreamingCall") != null);
}

